s=s.replace("tr<-tryCatch(if(is.factor(x))svychisq(~value+group,dd,statistic='F')else svyranktest(value~group,dd,test='wilcoxon'),error=function(e)e);if(inherits(tr,'error'))reason<-conditionMessage(tr)else p<-tr$p.value", "tr<-tryCatch(withCallingHandlers({stopifnot(length(unique(dd$variables$value))>1,length(unique(dd$variables$group))==length(unique(d$variables$group)),degf(dd)>0);if(is.factor(x))svychisq(~value+group,dd,statistic='F')else svyranktest(value~group,dd,test='wilcoxon')},warning=function(w){warn<<-paste(warn,conditionMessage(w),sep=';');invokeRestart('muffleWarning')}),error=function(e)e);if(inherits(tr,'error'))reason<-conditionMessage(tr)else {p<-tr$p.value;stat<-toJSON(as.list(tr$statistic),auto_unbox=TRUE);param<-toJSON(as.list(tr$parameter),auto_unbox=TRUE);method<-tr$method}")
